            {"author": "John Milton", "work": "Paradise Lost", "quote": "The solemn invocation of the heavenly Muse stands as an immortal **prologue** to the cosmic tragedy of man's fall."},
            {"author": "Alexander Pope", "work": "An Epistle to Dr. Arbuthnot", "quote": "To my sick soul, each trivial event seemed but a dark **prologue** to impending calamity."}
