            {"author": "Samuel Taylor Coleridge", "work": "Lectures on Shakespeare", "quote": "When the Chorus appears to **prologuize** in Henry V, poetry elevates historical chronicle into magnificent epic."},
            {"author": "Ben Jonson", "work": "Every Man in His Humour", "quote": "He chose to **prologuize** with sharp satirical verses aimed at the vulgar tastes of the pit."}
